#!/usr/bin/env python3
"""Añade a datos/idiomas_extra.json las traducciones de los consejos de la
pantalla de carga (ui/componentes/pantalla_carga.gd). Orden: es,en,pt,fr,it,de,ca,pl,tr."""
import json, pathlib
L = ["es","en","pt","fr","it","de","ca","pl","tr"]
T = [
("Consejo: los días de partido el estadio se llena más si el equipo viene ganando.","Tip: on match days the stadium fills up more when the team is winning.","Dica: nos dias de jogo o estádio enche mais quando a equipa vem a ganhar.","Astuce : les jours de match, le stade se remplit davantage quand l'équipe gagne.","Consiglio: nei giorni di partita lo stadio si riempie di più se la squadra vince.","Tipp: An Spieltagen füllt sich das Stadion mehr, wenn die Mannschaft gewinnt.","Consell: els dies de partit l'estadi s'omple més si l'equip va guanyant.","Wskazówka: w dni meczowe stadion zapełnia się bardziej, gdy drużyna wygrywa.","İpucu: Maç günlerinde takım kazanıyorsa stadyum daha çok dolar."),
("Consejo: el Centro médico acelera la recuperación entre partidos.","Tip: the Medical Centre speeds up recovery between matches.","Dica: o Centro médico acelera a recuperação entre jogos.","Astuce : le centre médical accélère la récupération entre les matchs.","Consiglio: il Centro medico accelera il recupero tra le partite.","Tipp: Das Medizinzentrum beschleunigt die Erholung zwischen den Spielen.","Consell: el Centre mèdic accelera la recuperació entre partits.","Wskazówka: Centrum medyczne przyspiesza regenerację między meczami.","İpucu: Sağlık merkezi maçlar arasındaki toparlanmayı hızlandırır."),
("Consejo: pulsa V al pasear para cambiar a primera persona.","Tip: press V while walking to switch to first person.","Dica: carregue em V ao passear para mudar para a primeira pessoa.","Astuce : appuyez sur V en vous promenant pour passer à la première personne.","Consiglio: premi V mentre cammini per passare alla prima persona.","Tipp: Drücke beim Spazieren V, um in die Ich-Perspektive zu wechseln.","Consell: prem V mentre passeges per canviar a primera persona.","Wskazówka: naciśnij V podczas spaceru, by przełączyć na widok z pierwszej osoby.","İpucu: Gezerken V'ye basarak birinci şahıs görünümüne geç."),
("Consejo: entra en las casas y los bares; la gente de la ciudad tiene cosas que contarte.","Tip: step into the houses and bars; the people of the city have things to tell you.","Dica: entre nas casas e nos bares; as pessoas da cidade têm coisas para lhe contar.","Astuce : entrez dans les maisons et les bars ; les habitants ont des choses à vous raconter.","Consiglio: entra nelle case e nei bar; la gente della città ha cose da raccontarti.","Tipp: Betritt die Häuser und Bars; die Menschen der Stadt haben dir etwas zu erzählen.","Consell: entra a les cases i als bars; la gent de la ciutat té coses per explicar-te.","Wskazówka: wchodź do domów i barów; mieszkańcy miasta mają ci wiele do opowiedzenia.","İpucu: Evlere ve barlara gir; şehrin insanlarının sana anlatacakları var."),
("Consejo: la Academia juvenil mejora el potencial de los canteranos.","Tip: the Youth Academy improves the potential of your academy players.","Dica: a Academia juvenil melhora o potencial dos jovens da formação.","Astuce : l'Académie des jeunes améliore le potentiel des jeunes du centre.","Consiglio: l'Accademia giovanile migliora il potenziale dei giovani del vivaio.","Tipp: Die Jugendakademie verbessert das Potenzial deiner Nachwuchsspieler.","Consell: l'Acadèmia juvenil millora el potencial dels jugadors de la pedrera.","Wskazówka: Akademia młodzieżowa podnosi potencjał wychowanków.","İpucu: Genç akademisi altyapı oyuncularının potansiyelini artırır."),
("Consejo: de noche las ventanas se encienden y las farolas alumbran la calle.","Tip: at night the windows light up and the street lamps glow.","Dica: à noite as janelas acendem-se e os candeeiros iluminam a rua.","Astuce : la nuit, les fenêtres s'allument et les lampadaires éclairent la rue.","Consiglio: di notte le finestre si accendono e i lampioni illuminano la strada.","Tipp: Nachts leuchten die Fenster und die Laternen erhellen die Straße.","Consell: de nit les finestres s'encenen i els fanals il·luminen el carrer.","Wskazówka: nocą zapalają się okna, a latarnie oświetlają ulicę.","İpucu: Geceleri pencereler yanar ve sokak lambaları yolu aydınlatır."),
("Construyendo la ciudad…","Building the city…","A construir a cidade…","Construction de la ville…","Costruzione della città…","Die Stadt wird gebaut…","Construint la ciutat…","Budowanie miasta…","Şehir inşa ediliyor…"),
("Levantando el estadio…","Raising the stadium…","A levantar o estádio…","Construction du stade…","Costruzione dello stadio…","Das Stadion wird errichtet…","Aixecant l'estadi…","Wznoszenie stadionu…","Stadyum yükseltiliyor…"),
]
ruta = pathlib.Path("datos/idiomas_extra.json")
d = json.loads(ruta.read_text(encoding="utf-8"))
for t in T:
    for i, lg in enumerate(L[1:], start=1):
        d.setdefault(lg, {})[t[0]] = t[i]
ruta.write_text(json.dumps(d, ensure_ascii=False, indent="\t"), encoding="utf-8")
print("consejos y mensajes:", len(T))
